function flipBlocks(head: ListNode | null, k: number): ListNode | null {
  const vals: number[] = [];
  for (let n = head; n; n = n.next) vals.push(n.val);
  for (let s = 0; s + k <= vals.length; s += k) {
    for (let i = s, j = s + k - 1; i < j; i++, j--) [vals[i], vals[j]] = [vals[j], vals[i]];
  }
  let out: ListNode | null = null;
  for (let i = vals.length - 1; i >= 0; i--) out = new ListNode(vals[i], out);
  return out;
}

