class Solution:
    def flipBlocks(self, head: Optional[ListNode], k: int) -> Optional[ListNode]:
        vals = []
        while head:
            vals.append(head.val)
            head = head.next
        for s in range(0, len(vals) - k + 1, k):
            vals[s:s + k] = vals[s:s + k][::-1]
        out = None
        for v in reversed(vals):
            out = ListNode(v, out)
        return out

