function flipBlocks(head: ListNode | null, k: number): ListNode | null {
  const dummy = new ListNode(0, head);
  let groupPrev: ListNode = dummy;
  for (;;) {
    let kth: ListNode | null = groupPrev;
    for (let i = 0; i < k && kth; i++) kth = kth.next;
    if (!kth) break; // fewer than k nodes left
    const after = kth.next;
    // reverse the block; starting prev at "after" links the new tail onward
    let prev: ListNode | null = after, cur = groupPrev.next;
    while (cur !== after) {
      const nxt: ListNode | null = cur!.next;
      cur!.next = prev;
      prev = cur;
      cur = nxt;
    }
    const first = groupPrev.next!; // old first node, now the block's last
    groupPrev.next = kth;
    groupPrev = first;
  }
  return dummy.next;
}

